{
  "name": "@tanstack/ai-opencode",
  "version": "1.0.1",
  "description": "OpenCode harness adapter for TanStack AI — run OpenCode as a chat backend with local tool execution and stateful sessions.",
  "author": "",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/TanStack/ai.git",
    "directory": "packages/ai-opencode"
  },
  "keywords": [
    "ai",
    "ai-sdk",
    "typescript",
    "tanstack",
    "opencode",
    "harness",
    "agent",
    "adapter",
    "chat",
    "tool-calling"
  ],
  "type": "module",
  "module": "./dist/esm/index.js",
  "types": "./dist/esm/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/esm/index.d.ts",
      "import": "./dist/esm/index.js"
    },
    "./byok": {
      "types": "./dist/esm/byok.d.ts",
      "import": "./dist/esm/byok.js"
    }
  },
  "files": [
    "dist",
    "src"
  ],
  "dependencies": {
    "@opencode-ai/sdk": "^1.17.4"
  },
  "peerDependencies": {
    "@tanstack/ai-sandbox": "^1.1.0",
    "@tanstack/ai": "^1.1.0"
  },
  "devDependencies": {
    "@vitest/coverage-v8": "4.1.10",
    "@tanstack/ai": "1.1.0",
    "@tanstack/ai-sandbox": "1.1.0"
  },
  "scripts": {
    "build": "vite build",
    "clean": "premove ./build ./dist",
    "lint:fix": "oxlint src --type-aware --fix",
    "test:build": "publint --strict",
    "test:oxlint": "oxlint src --type-aware",
    "test:coverage": "vitest run --coverage --coverage.include='src/**' --coverage.reporter=text-summary --coverage.reporter=json-summary",
    "test:lib": "vitest",
    "test:lib:dev": "pnpm test:lib --watch",
    "test:types": "tsc"
  }
}
